-- 193: Original BrillaPrep WASSCE BrillaPrep transitional Basketry beta content blueprint questions, part 1.
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_193_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_193_guard;
INSERT INTO _migration_193_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_basketry_b004_001' AND NOT (q.topic_id IS 'topic_was_basketry_b004_1' AND q.subject_id IS 'subj_wassce_basketry' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which attribute makes well-conditioned cane suitable for forming a curved basket handle?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. It bends with useful toughness without splitting","B. It is highly rigid and should remain straight under normal forming loads","C. It has useful bulk but cannot follow a controlled curve without fracturing","D. It stays excessively soft after soaking and recovers little structural stiffness"]' AND q.correct_answer IS 'A' AND q.explanation IS 'A handle needs a material that can follow a controlled curve while retaining tensile strength, so conditioned cane is selected for flexibility and toughness rather than complete rigidity. Therefore the correct answer is A: It bends with useful toughness without splitting.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_basketry_b004_1' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_basketry_b004_001' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Basketry practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_193_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_basketry_b004_002' AND NOT (q.topic_id IS 'topic_was_basketry_b004_1' AND q.subject_id IS 'subj_wassce_basketry' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which statement describes a material attribute rather than a use of that material?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Raffia is selected to wrap a coiled basket core","B. Raffia is woven into the decorative band of a table mat","C. A raffia strip is soft and flexible when properly conditioned","D. Raffia is tied around the finished rim of a lightweight tray"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Softness and flexibility are inherent working qualities that can be observed or tested; the other statements name applications and therefore describe uses rather than attributes. Therefore the correct answer is C: A raffia strip is soft and flexible when properly conditioned.' AND q.difficulty IS 'medium' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_basketry_b004_1' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_basketry_b004_002' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Basketry practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_193_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_basketry_b004_003' AND NOT (q.topic_id IS 'topic_was_basketry_b004_1' AND q.subject_id IS 'subj_wassce_basketry' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Why are properly prepared corn shucks suitable for plaited or wrapped basketry details?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Their untreated dry fibres bend repeatedly without conditioning or cracking","B. Their woody circular section carries the main load of a rigid basket frame","C. Their broad fibres become pliable when conditioned and can be folded closely","D. Their short cross-grain structure gives greater rim strength than mature cane"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Conditioned corn shucks provide broad flexible strips for folding, plaiting and wrapping, but they are not a substitute for sound cane where the design requires a stiff structural framework. Therefore the correct answer is C: Their broad fibres become pliable when conditioned and can be folded closely.' AND q.difficulty IS 'hard' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_basketry_b004_1' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_basketry_b004_003' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Basketry practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_193_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_basketry_b004_004' AND NOT (q.topic_id IS 'topic_was_basketry_b004_1' AND q.subject_id IS 'subj_wassce_basketry' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which quality makes prepared date-palm leaflets useful for light plaited basketry?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. They split into long flexible strips that interlace with regular spacing","B. They form a dense round rod intended mainly for heavy structural stakes","C. They normally remain ready to weave after long dry storage without reconditioning","D. Their crosswise strength is the main reason they can be split into long strips"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Sound date-palm leaflets can be dried, split and reconditioned into long strips whose lengthwise fibres support plaiting and light containers when thickness and defects are controlled. Therefore the correct answer is A: They split into long flexible strips that interlace with regular spacing.' AND q.difficulty IS 'easy' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_basketry_b004_1' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_basketry_b004_004' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Basketry practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_basketry_b004_001', 'topic_was_basketry_b004_1', 'subj_wassce_basketry', 'exam_wassce', NULL, NULL, 'Which attribute makes well-conditioned cane suitable for forming a curved basket handle?', 'multiple_choice', NULL, '["A. It bends with useful toughness without splitting","B. It is highly rigid and should remain straight under normal forming loads","C. It has useful bulk but cannot follow a controlled curve without fracturing","D. It stays excessively soft after soaking and recovers little structural stiffness"]', 'A', 'A handle needs a material that can follow a controlled curve while retaining tensile strength, so conditioned cane is selected for flexibility and toughness rather than complete rigidity. Therefore the correct answer is A: It bends with useful toughness without splitting.', 'easy', '1', '1', '90', NULL, NULL, '1', NULL, 'st_was_basketry_b004_1', 'Identify', 'AO1', NULL, NULL, 'board_waec');
