INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_basketry_b004_003', 'topic_was_basketry_b004_1', 'subj_wassce_basketry', 'exam_wassce', NULL, NULL, 'Why are properly prepared corn shucks suitable for plaited or wrapped basketry details?', 'multiple_choice', NULL, '["A. Their untreated dry fibres bend repeatedly without conditioning or cracking","B. Their woody circular section carries the main load of a rigid basket frame","C. Their broad fibres become pliable when conditioned and can be folded closely","D. Their short cross-grain structure gives greater rim strength than mature cane"]', 'C', 'Conditioned corn shucks provide broad flexible strips for folding, plaiting and wrapping, but they are not a substitute for sound cane where the design requires a stiff structural framework. Therefore the correct answer is C: Their broad fibres become pliable when conditioned and can be folded closely.', 'hard', '1', '1', '90', NULL, NULL, '1', NULL, 'st_was_basketry_b004_1', 'Explain', 'AO3', NULL, NULL, 'board_waec');
